javascript:
// =====================================================================
//  Asset Register 360 — الصق الكود ده في خانة "Javascript" في نفس الـ Report
//  مهم: اسم الريبورت هنا لازم يطابق اسم الـ Report بالظبط
// =====================================================================
const A360_STATUSES = [
	"Draft", "Submitted", "Partially Depreciated", "Fully Depreciated",
	"Sold", "Scrapped", "In Maintenance", "Out of Order", "Issue", "Receipt",
	"Capitalized", "Decapitalized", "Work In Progress", "Cancelled",
];

function a360_link_options(doctype, extra) {
	return function (txt) {
		let f = {};
		if (extra) f = extra();
		return frappe.db.get_link_options(doctype, txt, f);
	};
}

frappe.query_reports["Asset Register 360"] = {
	filters: [
		{
			fieldname: "company", label: __("Company"), fieldtype: "Link", options: "Company",
			default: frappe.defaults.get_user_default("Company"), reqd: 1,
		},
		{
			fieldname: "from_date", label: __("From Date"), fieldtype: "Date",
			default: frappe.datetime.year_start(), reqd: 1,
		},
		{
			fieldname: "to_date", label: __("To Date"), fieldtype: "Date",
			default: frappe.datetime.get_today(), reqd: 1,
		},
		{
			fieldname: "status", label: __("Status"), fieldtype: "MultiSelectList",
			get_data: function (txt) {
				txt = (txt || "").toLowerCase();
				return A360_STATUSES
					.filter((s) => !txt || s.toLowerCase().includes(txt))
					.map((s) => ({ value: s, description: "" }));
			},
		},
		{
			fieldname: "asset_category", label: __("Asset Category"), fieldtype: "MultiSelectList",
			get_data: a360_link_options("Asset Category"),
		},
		{
			fieldname: "location", label: __("Location"), fieldtype: "MultiSelectList",
			get_data: a360_link_options("Location"),
		},
		{
			fieldname: "cost_center", label: __("Cost Center"), fieldtype: "MultiSelectList",
			get_data: a360_link_options("Cost Center", () => ({
				company: frappe.query_report.get_filter_value("company"),
			})),
		},
		{
			fieldname: "department", label: __("Department"), fieldtype: "MultiSelectList",
			get_data: a360_link_options("Department"),
		},
		{
			fieldname: "asset", label: __("Asset"), fieldtype: "MultiSelectList",
			get_data: a360_link_options("Asset", () => ({
				company: frappe.query_report.get_filter_value("company"),
			})),
		},
		{ fieldname: "item_code", label: __("Item"), fieldtype: "Link", options: "Item",
			get_query: () => ({ filters: { is_fixed_asset: 1 } }) },
		{ fieldname: "custodian", label: __("Custodian"), fieldtype: "Link", options: "Employee" },
		{ fieldname: "supplier", label: __("Supplier"), fieldtype: "Link", options: "Supplier" },
		{ fieldname: "purchase_invoice", label: __("Purchase Invoice"), fieldtype: "Link",
			options: "Purchase Invoice" },
		{
			fieldname: "source_type", label: __("Source Type"), fieldtype: "Select",
			options: ["", "Purchase Invoice", "Purchase Receipt", "Asset Capitalization",
				"Opening (Existing Asset)", "Manual"],
		},
		{ fieldname: "finance_book", label: __("Finance Book"), fieldtype: "Link", options: "Finance Book" },
		{ fieldname: "include_default_book", label: __("Include Default FB Entries"),
			fieldtype: "Check", default: 1 },
		{
			fieldname: "group_by", label: __("Group By"), fieldtype: "Select",
			options: ["", "Asset Category", "Location", "Cost Center", "Department", "Status",
				"Supplier", "Source Type", "Custodian", "Item", "Purchase Year"],
		},
		{ fieldname: "summary_only", label: __("Group Totals Only"), fieldtype: "Check", default: 0,
			depends_on: "eval:doc.group_by" },
		{ fieldname: "include_disposed_before", label: __("Show Assets Disposed Before Period"),
			fieldtype: "Check", default: 0 },
		{ fieldname: "hide_zero_rows", label: __("Hide Zero Rows"), fieldtype: "Check", default: 0 },
	],

	formatter: function (value, row, column, data, default_formatter) {
		value = default_formatter(value, row, column, data);
		if (!data) return value;
		if (data.is_total) return `<b style="color:var(--text-color)">${value}</b>`;
		if (data.is_group) return `<b style="color:var(--primary)">${value}</b>`;

		if (column.fieldname === "status" && data.status) {
			const colors = {
				"Draft": "orange", "Submitted": "blue", "Partially Depreciated": "blue",
				"Fully Depreciated": "green", "Sold": "red", "Scrapped": "red",
				"Capitalized": "purple", "Cancelled": "grey", "In Maintenance": "yellow",
				"Out of Order": "red",
			};
			return `<span class="indicator-pill ${colors[data.status] || "gray"}">${__(data.status)}</span>`;
		}
		if (column.fieldname === "variance" && Math.abs(data.variance || 0) > 0.5) {
			return `<span style="color:var(--red-500);font-weight:600">${value}</span>`;
		}
		if (column.fieldname === "gain_loss" && data.gain_loss) {
			const c = data.gain_loss < 0 ? "var(--red-500)" : "var(--green-500)";
			return `<span style="color:${c};font-weight:600">${value}</span>`;
		}
		return value;
	},

	onload: function (report) {
		report.page.add_inner_button(__("Reset Filters"), function () {
			report.filters.forEach((f) => {
				if (!["company", "from_date", "to_date", "include_default_book"].includes(f.df.fieldname)) {
					f.set_value(f.df.fieldtype === "Check" ? 0 : (f.df.fieldtype === "MultiSelectList" ? [] : ""));
				}
			});
		});
	},
};
